import sys, io
md, hist = sys.argv[1], sys.argv[2]   # CLAUDE.md, CLAUDE-history.md
s = io.open(md, encoding='utf-8').read()
def R(old, new):
    global s
    assert s.count(old) == 1, old[:80]
    s = s.replace(old, new)
R("DO to DP, DQ to DR and DS to DX committed, waiting for her push.", "DO to DP, DQ to DR, DS to DX and DZ to EB committed, waiting for her push.")
R("- Push: DO to DP, DQ to DR and DS to DX (three commits).", "- Push: DO to DP, DQ to DR, DS to DX and DZ to EB (four commits).")
